import{c as t,Q as o,j as s,m as a}from"./chunks/framework.DjobWxAB.js";const u=JSON.parse('{"title":"rbq_example_level_0","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/examples/rbq_example_Level0.md","filePath":"software/examples/rbq_example_Level0.md","lastUpdated":1779182288000}'),i={name:"software/examples/rbq_example_Level0.md"};function r(n,e,l,d,c,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="rbq-example-level-0" tabindex="-1">rbq_example_level_0 <a class="header-anchor" href="#rbq-example-level-0" aria-label="Permalink to &quot;rbq_example_level_0&quot;">​</a></h1><p>Sample C++ application under <strong><code>rbq_examples</code></strong> that demonstrates <strong>low-level (LV0-style)</strong> communication with the RBQ stack: subscribe to IMU, joystick, and leg joint topics, publish leg motion references and joint-ownership commands, and optionally run a <strong>learned walking policy (ONNX)</strong> passed on the command line.</p><p>Before building or running this example, build and install <a href="/RBQ/software/rbq-sdk.html"><strong>RBQ SDK</strong></a>. Without the SDK (or if CMake cannot find it), the <code>rbq_examples</code> build will fail.</p><h2 id="behavior-summary" tabindex="-1">Behavior summary <a class="header-anchor" href="#behavior-summary" aria-label="Permalink to &quot;Behavior summary&quot;">​</a></h2><ul><li>A <strong>control loop</strong> thread exchanges DDS messages with the running RBQ motion stack (hardware or <strong>simulation</strong> started with <code>scripts/sim.bash</code>).</li><li><strong>Idle</strong>: tracks the stack’s final leg reference and publishes a compatible <code>MotionRef</code>.</li><li><strong>Motion</strong> (sit / stand keys): uses <code>JointControl</code> to interpolate poses, then publishes references and ownership as needed.</li><li><strong>Walk / Control</strong>: loads <strong>policy</strong> from <code>-p</code>, runs ONNX inference with IMU + joint + command observations, publishes <code>MotionRef</code> with policy gains.</li></ul><h2 id="build-rbq-examples" tabindex="-1">Build (<code>rbq_examples/</code>) <a class="header-anchor" href="#build-rbq-examples" aria-label="Permalink to &quot;Build (`rbq_examples/`)&quot;">​</a></h2><ol><li><p>Install dependencies per repository scripts (for ONNX, see <code>rbq_examples/scripts/install/apt.bash</code>, etc.).</p></li><li><p>Ensure <strong><code>rbq_sdk</code></strong> is installed; if not in the default prefix, add the install prefix to <code>CMAKE_PREFIX_PATH</code>.</p></li><li><p>From <strong><code>rbq_examples</code></strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # system dependencies, etc. (do not run setup.bash with sudo)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Per the build script, outputs are placed under the project’s <strong><code>bin/</code></strong>, etc.</p></li></ol><h2 id="policy-bundle-p" tabindex="-1">Policy bundle (<code>-p</code>) <a class="header-anchor" href="#policy-bundle-p" aria-label="Permalink to &quot;Policy bundle (`-p`)&quot;">​</a></h2><p>Walking mode needs a <strong>policy directory</strong> containing <strong><code>info.json</code></strong> and the ONNX expected by <code>rbq_sdk::Policy</code> / <code>PolicyParams</code>.</p><p>Example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_example_level_0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./../resources/policy/rbq10_trot/</span></span></code></pre></div><p>The application <strong>requires <code>-p</code></strong>.</p><h2 id="run-with-simulation" tabindex="-1">Run with simulation <a class="header-anchor" href="#run-with-simulation" aria-label="Permalink to &quot;Run with simulation&quot;">​</a></h2><ol><li><p>From the <strong>RBQ repository root</strong>, start the stack (sim Motion + MuJoCo + GUI) per the <a href="/RBQ/software/developers-guide.html">Developers guide</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span></span></code></pre></div></li><li><p>In the GUI, follow the manual for <strong>simulator connect</strong>, then <strong>control start</strong>. For the stack to be controllable, <strong>Auto Start</strong> (or equivalent) must bring the motion/control path up; skipping steps can prevent the example from receiving topics.</p></li><li><p>After building, from <strong><code>rbq_examples</code></strong>, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_example_level_0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./../resources/policy/rbq10_trot/</span></span></code></pre></div></li></ol><p>Use <strong><code>sudo</code></strong> if you need the <strong>real-time</strong> control thread path; without root, a normal thread is used.</p><h2 id="keyboard-and-controls" tabindex="-1">Keyboard and controls <a class="header-anchor" href="#keyboard-and-controls" aria-label="Permalink to &quot;Keyboard and controls&quot;">​</a></h2><p>A help screen is printed at startup. Typical bindings (exact list: source <code>printHelp()</code>):</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>q</code></td><td>Quit</td></tr><tr><td><code>z</code></td><td>Motion sit / ground sequence</td></tr><tr><td><code>x</code></td><td>Motion stand / ready sequence</td></tr><tr><td><code>c</code></td><td><strong>Control / walk</strong> mode (uses policy from <code>-p</code>)</td></tr></tbody></table><p>In control mode, <strong>gamepad</strong> axes provide velocity-style commands (see on-screen help).</p><h2 id="dds-topics" tabindex="-1">DDS topics <a class="header-anchor" href="#dds-topics" aria-label="Permalink to &quot;DDS topics&quot;">​</a></h2><p>The example uses string topics such as:</p><ul><li>Subscribe: <code>rt/rbq/cmd/joy/final</code>, <code>rt/rbq/info/imu</code>, <code>rt/rbq/info/leg_joint</code>, <code>rt/rbq/ref/leg_joint/final</code>, etc.</li><li>Publish: <code>rt/rbq/ref/leg_joint/owner_20</code>, <code>rt/rbq/cmd/motion/joint_owner/20</code>, etc.</li></ul><p>Exact names and semantics must match the <strong>robot software version</strong> you run.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>No motion / no topics</strong>: Check that <code>sim.bash</code> (or the hardware stack) is running and DDS uses the correct network interface.</li><li><strong>Policy errors</strong>: Check <code>-p</code> is valid, ONNX matches the installed <strong>onnxruntime</strong>, and <code>info.json</code> type (<code>rbq10</code>, <code>rbq10_trot</code>, etc.) matches.</li><li><strong>apt authentication errors</strong>, etc.: fix host GPG/sources separately; not specific to this example.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/software/rbq-sdk.html">RBQ SDK</a></li><li><a href="/RBQ/manual/Guides/developer-level-0.html">Level 0 Developer Guide</a></li><li><a href="/RBQ/software/Concept.html">Concept — Low level / LV0</a></li></ul>',27)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
